using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class PreparedAdvanceIntegrationTests
{
    [Fact]public void ALoadedGenerationWithSameRevisionCannotBeOverwrittenByOldSpeculation()
    {
        var source=new WorldSession(ContractFixture.Create());source.SetPaused(false);var host=new WorldSessionHost(source);var ready=source.CaptureAdvance(5,source.Revision).Prepare();var world=source.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"hakutai-advance-load",Guid.NewGuid().ToString("N")),world.Definitions);store.Save(source,"manual",world.WorldId);Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("manual"),source,source.Revision));Assert.Equal(source.Revision,host.Current.Revision);Assert.NotSame(source,host.Current);string loaded=ContractJson.CanonicalHash(host.Current.DiagnosticSnapshot());Assert.Equal(ResultCode.StateChanged,host.CommitAdvance(ready,out var publication));Assert.Null(publication);Assert.Equal(loaded,ContractJson.CanonicalHash(host.Current.DiagnosticSnapshot()));
    }
    [Fact]public async Task CompactPopulationTravelPublishesExactlyTheSynchronousWorldAndPosition()
    {
        var records=Enumerable.Range(0,100).Select(i=>NewGameWorldTests.Officer("created:advance-load-"+i,site:NationalRoutes.Sites[i%NationalRoutes.Sites.Length].Id.Value)).ToArray();var setup=NewGameWorldTests.Setup(records);var source=new WorldSession(NewGameWorld.Create(setup.World,setup.Registered,"person:nobunaga",personalAuthorityLayout:NewGameWorld.CompactPersonalAuthority));Assert.Equal(ResultCode.Accepted,source.Submit(TravelWorld.Move(source.DiagnosticSnapshot(),"request:prepared-trip","fork"),source.Revision).Code);source.SetPaused(false);var expected=new WorldSession(source.DiagnosticSnapshot());expected.AdvanceTo(5);string before=ContractJson.CanonicalHash(source.DiagnosticSnapshot());var host=new WorldSessionHost(source);var ready=await source.CaptureAdvance(5,source.Revision).PrepareAsync();Assert.Equal(before,ContractJson.CanonicalHash(source.DiagnosticSnapshot()));Assert.Equal(ResultCode.Accepted,host.CommitAdvance(ready,out var publication));Assert.Equal(ContractJson.Write(expected.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(expected.GetBranchView(expected.PlayerControl)),ContractJson.Write(host.Current.GetBranchView(host.Current.PlayerControl)));Assert.Equal(ContractJson.Write(host.Current.DiagnosticSnapshot()),ContractJson.Write(publication!.Display));
    }
    [Fact]public async Task RealMilitaryAuthorityAndIssuedFormationRemainPrivateUntilAtomicPublication()
    {
        var setup=NewGameWorldTests.Setup([]);var source=new WorldSession(NewGameWorld.Create(setup.World,[],"person:shingen",personalAuthorityLayout:NewGameWorld.CompactPersonalAuthority));
        void Send(NewMilitaryAction a){Assert.Equal(ResultCode.Accepted,source.DecideNewMilitary(new(new("request:prepared-military/"+source.Revision),a){AuthorityPolicy=a==NewMilitaryAction.Request?NewGameMilitary.AuthorityContract:null},source.PlayerControl,source.Revision).Code);}
        void Open(){foreach(var m in source.GetActorView(source.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,source.Open(source.PlayerControl,m.Id,source.Revision).Code);}
        Send(NewMilitaryAction.Request);NewGameWorldTests.At(source,2);Open();Send(NewMilitaryAction.Accept);NewGameWorldTests.At(source,4);Open();Send(NewMilitaryAction.Pickup);Assert.Equal(ResultCode.Accepted,source.DecideNewMilitary(new(new("request:prepared-load"),NewMilitaryAction.Load,100000),source.PlayerControl,source.Revision).Code);Send(NewMilitaryAction.Deploy);var a=NewGameMilitary.Anchor(source.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,source.DecideNewMilitary(new(new("request:prepared-line"),NewMilitaryAction.Form,0,new(a.X+20000,a.Y-12000),new(a.X+20000,a.Y+12000)),source.PlayerControl,source.Revision).Code);source.SetPaused(false);var expected=new WorldSession(source.DiagnosticSnapshot());long target=source.Seconds+3;expected.AdvanceTo(target);var host=new WorldSessionHost(source);string before=ContractJson.CanonicalHash(source.DiagnosticSnapshot());var ready=await source.CaptureAdvance(target,source.Revision).PrepareAsync();Assert.Equal(before,ContractJson.CanonicalHash(source.DiagnosticSnapshot()));Assert.Equal(ResultCode.Accepted,host.CommitAdvance(ready,out _));Assert.Equal(ContractJson.Write(expected.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(expected.GetBranchView(expected.PlayerControl)),ContractJson.Write(host.Current.GetBranchView(host.Current.PlayerControl)));Assert.Single(host.Current.DiagnosticSnapshot().NewMilitary!.Authority!.Grants);
    }
    [Theory][InlineData(false)][InlineData(true)]public async Task ExistingNpcAndRegionalWorkProfilesKeepExactlyTheSamePrivateFuture(bool npc)
    {
        var source=new WorldSession(npc?NpcWork.Create():RegionalWork.Create());source.SetPaused(false);var before=source.DiagnosticSnapshot();var expected=new WorldSession(before);expected.AdvanceTo(10);var host=new WorldSessionHost(source);var ready=await source.CaptureAdvance(10,source.Revision).PrepareAsync();Assert.Equal(ContractJson.Write(before),ContractJson.Write(source.DiagnosticSnapshot()));Assert.Equal(ResultCode.Accepted,host.CommitAdvance(ready,out _));Assert.Equal(ContractJson.Write(expected.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));
    }
}
